package org.worldmedals.atlas;
import android.app.*;import android.content.*;import android.widget.*;import android.view.*;import android.util.Base64;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import android.security.keystore.*;import java.security.KeyStore;import java.nio.charset.StandardCharsets;
final class UpdateAuth {
 static SecretKey key() throws Exception {KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);if(!s.containsAlias("atlas-updates")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("atlas-updates",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes("GCM").setEncryptionPaddings("NoPadding").build());g.generateKey();}return (SecretKey)s.getKey("atlas-updates",null);}
 static String read(Activity a) throws Exception {SharedPreferences p=a.getPreferences(0);String data=p.getString("updateToken",null);if(data==null)return "";Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(p.getString("updateIv",""),0)));return new String(c.doFinal(Base64.decode(data,0)),StandardCharsets.UTF_8);}
 static void show(Activity a,Runnable saved){EditText input=new EditText(a);input.setSingleLine(true);input.setInputType(129);input.setHint("粘贴 GitHub 只读令牌");input.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);
 AlertDialog d=new AlertDialog.Builder(a).setTitle("私有仓库更新授权").setMessage("仅选择 world-medals，Contents 设为 Read-only。令牌加密保存在本机，只向 api.github.com 发送以检查更新。").setView(input).setPositiveButton("保存并检查",null).setNegativeButton("取消",(x,w)->input.setText("")).setNeutralButton("清除授权",(x,w)->{a.getPreferences(0).edit().remove("updateToken").remove("updateIv").apply();input.setText("");Toast.makeText(a,"已清除本机授权",Toast.LENGTH_SHORT).show();}).create();
 d.setOnShowListener(x->{d.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);d.getButton(-1).setOnClickListener(v->{String token=input.getText().toString().trim();if(!token.matches("github_pat_[A-Za-z0-9_]+")){input.setError("请填写 fine-grained 令牌");return;}try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());String encrypted=Base64.encodeToString(c.doFinal(token.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);a.getPreferences(0).edit().putString("updateToken",encrypted).putString("updateIv",Base64.encodeToString(c.getIV(),Base64.NO_WRAP)).remove("lastAttempt").apply();input.setText("");d.dismiss();saved.run();}catch(Exception e){input.setError("本机加密保存失败");}});});d.show();}
}
